import { demoLookVideoId } from '@/lib/demoLookAr';
import type { CelebrityVideo, Product, StyleLook } from '@/types';

/**
 * The six demo looks shipped in every build (generated by scripts/data/build_demo_look_bundle.py from the files the
 * backend serves). They open and paint with no backend answer; the API still refreshes them when it responds.
 */
const bundle = require('./demoLookBundle.json') as {
  products: Product[];
  celebrityVideos: CelebrityVideo[];
  styleLooks: StyleLook[];
};

export const DEMO_LOOK_PRODUCTS: Product[] = bundle.products;
export const DEMO_CELEBRITY_VIDEOS: CelebrityVideo[] = bundle.celebrityVideos;
export const DEMO_STYLE_LOOKS: StyleLook[] = bundle.styleLooks;

export function demoLookProduct(id: string): Product | undefined {
  return DEMO_LOOK_PRODUCTS.find((product) => product.id === id);
}

export function demoCelebrityVideo(id: string | undefined): CelebrityVideo | undefined {
  return id ? DEMO_CELEBRITY_VIDEOS.find((video) => video.id === demoLookVideoId(id)) : undefined;
}

export function demoStyleLook(id: string | undefined): StyleLook | undefined {
  return id ? DEMO_STYLE_LOOKS.find((look) => look.id === demoLookVideoId(id)) : undefined;
}
